<!doctype html>
<html lang="en">
<head>
    <meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
    <meta name="description" content="Closer is a conversation game for dates, friends and family.">
    <meta name="theme-color" content="#3a1230"><title>Closer — conversation games for real time together</title>
    <style>
        :root{--plum:#3a1230;--deep:#240a1c;--burgundy:#7a1f43;--rose:#e5a9b3;--peach:#f6c7a8;--amber:#e5a53a;--cream:#fcf6ee;--soft:#f6ebdd;--ink:#4a3342;--ease:cubic-bezier(.2,.8,.2,1)}
        *{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--cream);color:var(--plum);font-family:Inter,ui-sans-serif,system-ui,sans-serif;-webkit-font-smoothing:antialiased}a{color:inherit}.wrap{width:min(1120px,calc(100% - 40px));margin:auto}.serif{font-family:Fraunces,Georgia,serif;letter-spacing:-.035em}
        header{position:absolute;inset:0 0 auto;z-index:2;border-bottom:1px solid #fcf6ee29}.nav{display:flex;align-items:center;justify-content:space-between;min-height:78px}.brand{display:inline-flex;align-items:center;gap:10px;color:var(--cream);text-decoration:none;font:600 28px/1 Fraunces,Georgia,serif}.mark{width:34px;height:34px}.nav-links{display:flex;align-items:center;gap:26px;font-size:14px;font-weight:700}.nav-links a{color:var(--cream);text-decoration:none;opacity:.86;transition:opacity .15s var(--ease)}.nav-links a:hover{opacity:1}.nav-cta{padding:12px 19px;border-radius:999px;background:var(--cream);color:var(--plum)!important;opacity:1!important}
        .hero{min-height:720px;padding:150px 0 90px;overflow:hidden;background:var(--plum);color:var(--cream)}.hero-grid{display:grid;grid-template-columns:minmax(0,.95fr) minmax(360px,1.05fr);align-items:center;gap:80px}.eyebrow,.section-kicker{margin:0 0 22px;color:var(--peach);font-size:12px;font-weight:800;letter-spacing:.18em;text-transform:uppercase}.hero h1{max-width:600px;margin:0;font-size:clamp(3.8rem,8vw,7.2rem);line-height:.91;font-weight:600}.hero-copy{max-width:490px;margin:28px 0 0;color:#f5deda;font-size:19px;line-height:1.55}.actions{display:flex;flex-wrap:wrap;gap:14px;margin-top:34px}.button{display:inline-flex;min-height:50px;align-items:center;justify-content:center;padding:0 22px;border:2px solid transparent;border-radius:999px;font-size:15px;font-weight:750;text-decoration:none;transition:transform .15s var(--ease),background .15s var(--ease)}.button:hover{transform:translateY(-2px)}.button:active{transform:translateY(1px) scale(.985)}.button-primary{background:var(--amber);color:var(--deep)}.button-primary:hover{background:var(--peach)}.button-quiet{border-color:#fcf6ee8c;color:var(--cream)}.button-quiet:hover{background:#fcf6ee1a}
        .hero-art{position:relative;min-height:430px;display:grid;place-items:center}.art-card{position:relative;width:min(100%,470px);min-height:360px;padding:26px;border-radius:34px;background:var(--cream);color:var(--plum);box-shadow:0 28px 70px #14000f47;transform:rotate(2deg)}.art-card:before{content:"";position:absolute;inset:-18px 24px 18px -24px;z-index:-1;border-radius:34px;background:var(--burgundy);transform:rotate(-6deg)}.art-top{display:flex;justify-content:space-between;color:var(--burgundy);font-size:11px;font-weight:800;letter-spacing:.14em;text-transform:uppercase}.art-question{margin:42px 0 28px;font-size:clamp(2rem,4vw,3.4rem);line-height:.98}.answer{display:flex;align-items:center;gap:12px;margin-top:11px;padding:14px 16px;border:2px solid #3a123026;border-radius:16px;font-weight:700}.answer:before{content:"";width:12px;height:12px;border:2px solid currentColor;border-radius:50%}.selected{border-color:var(--burgundy);background:#7a1f431a}.selected:before{background:var(--amber);border-color:var(--amber);box-shadow:inset 0 0 0 3px var(--cream)}
        section{padding:110px 0}.section-intro{max-width:620px}.section-kicker{color:var(--burgundy);margin-bottom:14px}.section-intro h2,.games h2,.cta h2{margin:0;font-size:clamp(2.7rem,5vw,5rem);line-height:.98;font-weight:600}.section-lead{margin:22px 0 0;color:var(--ink);font-size:18px;line-height:1.6}.feature-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:58px}.feature{min-height:260px;padding:28px;border-radius:26px;background:var(--soft)}.feature:nth-child(2){background:var(--peach)}.feature:nth-child(3){background:var(--rose)}.feature-number{display:grid;width:42px;height:42px;place-items:center;border-radius:50%;background:var(--amber);color:var(--deep);font:700 20px Georgia,serif}.feature h3{margin:42px 0 10px;font:600 28px/1.05 Fraunces,Georgia,serif;letter-spacing:-.025em}.feature p{margin:0;color:var(--ink);line-height:1.55}
        .games{background:var(--soft)}.games-grid{display:grid;grid-template-columns:1.15fr .85fr;gap:60px;align-items:end}.game-list{display:grid;gap:14px;margin-top:42px}.game{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:20px 0;border-bottom:1px solid #3a123033;text-decoration:none}.game strong{font:600 27px/1 Fraunces,Georgia,serif}.game span{color:var(--burgundy);font-size:24px;transition:transform .15s var(--ease)}.game:hover span{transform:translateX(4px)}.circles{position:relative;min-height:360px;border-radius:30px;overflow:hidden;background:var(--plum)}.circles i{position:absolute;display:block;width:190px;height:190px;border-radius:50%;opacity:.9}.circles i:nth-child(1){top:48px;left:46px;background:var(--rose)}.circles i:nth-child(2){top:118px;left:134px;background:var(--amber)}.circles i:nth-child(3){top:62px;right:42px;background:var(--burgundy)}.circles i:nth-child(4){right:90px;bottom:22px;background:var(--peach)}
        .cta{padding:100px 0;background:var(--burgundy);color:var(--cream);text-align:center}.cta h2{max-width:700px;margin:auto}.cta p{max-width:520px;margin:22px auto 0;color:#f5deda;line-height:1.6}.cta .actions{justify-content:center}footer{padding:30px 0;background:var(--deep);color:#f5deda;font-size:13px}.footer-row{display:flex;align-items:center;justify-content:space-between;gap:20px}.footer-row a{color:var(--cream);font-weight:700;text-decoration:none}
        [data-enter]>div>*{animation:rise .75s var(--ease) both}[data-enter]>div>*:nth-child(2){animation-delay:.08s}.hero-art{animation:settle 1.1s var(--ease) .1s both}@keyframes rise{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}@keyframes settle{from{opacity:0;transform:scale(.96) rotate(2deg)}to{opacity:1;transform:scale(1) rotate(2deg)}}:focus-visible{outline:3px solid var(--amber);outline-offset:4px}@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation-duration:.01ms!important;transition-duration:.01ms!important}html{scroll-behavior:auto}}
        @media(max-width:760px){.wrap{width:min(calc(100% - 32px),560px)}.nav{min-height:70px}.nav-links a:not(.nav-cta){display:none}.hero{min-height:auto;padding:124px 0 70px}.hero-grid,.games-grid{grid-template-columns:1fr;gap:54px}.hero-art{min-height:330px}.art-card{min-height:320px}section{padding:76px 0}.feature-grid{grid-template-columns:1fr;margin-top:38px}.feature{min-height:auto}.feature h3{margin-top:28px}.circles{min-height:270px}.circles i{width:145px;height:145px}.circles i:nth-child(1){top:30px;left:24px}.circles i:nth-child(2){top:86px;left:100px}.circles i:nth-child(3){top:34px;right:18px}.circles i:nth-child(4){right:62px;bottom:-22px}.footer-row{align-items:flex-start;flex-direction:column}}
    </style>
</head>
<body>
    <header><div class="wrap nav"><a class="brand" href="{{ url('/') }}" aria-label="Closer home"><svg class="mark" viewBox="0 0 64 64" aria-hidden="true"><circle cx="25" cy="32" r="14" fill="#e5a9b3"/><circle cx="39" cy="32" r="14" fill="#e5a53a" fill-opacity=".85"/></svg>Closer</a><nav class="nav-links" aria-label="Main navigation"><a href="#how-it-works">How it works</a><a href="#games">Games</a><a class="nav-cta" href="https://play.playcloser.app">Play Closer ↗</a></nav></div></header>
    <main>
        <section class="hero" data-enter aria-labelledby="hero-title"><div class="wrap hero-grid"><div><p class="eyebrow">Conversation games for real time together</p><h1 id="hero-title" class="serif">Make room for a better conversation.</h1><p class="hero-copy">Closer gives dates, friends and family a simple way to ask, answer and discover something new.</p><div class="actions"><a class="button button-primary" href="https://play.playcloser.app">Play Closer ↗</a><a class="button button-quiet" href="#how-it-works">See how it works</a></div></div><div class="hero-art" aria-label="A Closer conversation game round"><div class="art-card"><div class="art-top"><span>Blind Reveal</span><span>Round 3</span></div><p class="art-question serif">Would you rather take the long way home or stay out a little longer?</p><div class="answer">Take the long way home</div><div class="answer selected">Stay out a little longer</div></div></div></div></section>
        <section id="how-it-works" aria-labelledby="how-title"><div class="wrap"><div class="section-intro"><p class="section-kicker">How it works</p><h2 id="how-title" class="serif">The game is easy. The answers are yours.</h2><p class="section-lead">Start a room, choose a game and share the code. No account is needed to join.</p></div><div class="feature-grid"><article class="feature"><span class="feature-number">1</span><h3>Choose your people</h3><p>Date night for two, or a group of up to six with friends and family.</p></article><article class="feature"><span class="feature-number">2</span><h3>Pick a game</h3><p>Use Conversation Cards, Blind Reveal or Guess Me for the mood you are in.</p></article><article class="feature"><span class="feature-number">3</span><h3>Start connecting</h3><p>Answer, reveal, laugh and talk. The game handles the next prompt.</p></article></div></div></section>
        <section id="games" class="games" aria-labelledby="games-title"><div class="wrap games-grid"><div><p class="section-kicker">Games to play</p><h2 id="games-title" class="serif">Something for the people you brought.</h2><div class="game-list"><a class="game" href="https://play.playcloser.app"><strong>Conversation Cards</strong><span>↗</span></a><a class="game" href="https://play.playcloser.app"><strong>Blind Reveal</strong><span>↗</span></a><a class="game" href="https://play.playcloser.app"><strong>Guess Me</strong><span>↗</span></a></div></div><div class="circles" aria-hidden="true"><i></i><i></i><i></i><i></i></div></div></section>
        <section class="cta" aria-labelledby="cta-title"><div class="wrap"><h2 id="cta-title" class="serif">Put the phones to one good use.</h2><p>Play together in your browser, wherever everyone happens to be.</p><div class="actions"><a class="button button-primary" href="https://play.playcloser.app">Play Closer ↗</a><a class="button button-quiet" href="{{ url('/admin') }}">Open admin panel</a></div></div></section>
    </main>
    <footer><div class="wrap footer-row"><span>© {{ date('Y') }} Closer</span><a href="{{ url('/admin') }}">Admin panel ↗</a></div></footer>
</body>
</html>
